from pathlib import Path
import json
p=Path('training/v13-selfplay');r=json.loads((p/'results.json').read_text());a=r['initial'];b=r['mcts'];c=r['primaryFinalMinusInitial'];t=r['training']
lines=['# V13：无搜索学生的自我对局强化学习','','**结论：学生直接行动确实很快，但独立玩游戏的能力不足；本轮基于终局成败的训练没有观察到成功率提升。**','','## 初始能力和速度','','初始模型固定选V11验证策略KL最低的种子，不根据实战成绩选取。学生每步直接执行概率最高的合法动作，不展开搜索树；仍使用冻结查表评分作为输入和固定logit的一部分，不是完全脱离查表的神经网络。','','| 控制方式 | 合出1536 | 本机平均决策耗时/步 |','|---|---:|---:|',f"| 初始学生直接行动 | {a['wins'][0]}/512 | {a['decisionMicrosecondsPerMove']:.2f}微秒 |",f"| 原MCTS（1毫秒软预算） | {b['wins'][0]}/512（{b['meanPercent']:.2f}%） | {b['decisionMicrosecondsPerMove']:.2f}微秒 |",'',f"初始学生单次决策耗时约为MCTS的1/{r['speedupInitialVsMCTS']:.0f}。这是本机当前配置下的计算时间比，不是相同实力的加速比；耗时统计不含游戏环境推进。",'', '## 真正使用游戏结果训练','','三个独立训练种子，各8192局正常开局，共24576局。每2048局保存一轮模型。行为策略以温度0.1采样探索，最终合出1536给1、死亡给0，不使用中途合并分数。采用REINFORCE策略梯度，上一批次的分阶段成功率作为减方差基线；每批64局。旧训练局面上对初始学生概率分布施加小权重KL约束，以限制遗忘。旧老师Q标签未参与本轮训练。','','| 训练种子 | 总对局 | 成功次数 | 行动步数 | 训练CPU秒 |','|---|---:|---:|---:|---:|']
for s,x in t.items():lines.append(f"| {s} | {x['episodes']} | {x['wins']} | {x['steps']} | {x['cpuSeconds']:.2f} |")
lines+=['',f"训练共只产生{sum(x['wins'] for x in t.values())}次成功反馈。大量快速对局主要提供失败结果，未形成稳定的成功行为供策略强化。这是本轮暴露出的稀疏奖励问题；不是证明自我对局强化学习普遍无效。",'', '## 四轮独立开局评估','','每份模型用相同512个新开局评估，执行贪心动作；训练中的随机探索成功率与此不同。最终第四轮是预先指定的主要终点，不从四轮中挑最好的。','','| 每个模型已训练局数 | 种子1成功局数 | 种子2 | 种子3 |','|---|---:|---:|---:|']
for i,x in r['rounds'].items():lines.append(f"| {int(i)*2048} | {x['wins'][0]}/512 | {x['wins'][1]}/512 | {x['wins'][2]}/512 |")
lines+=['', '所有测试零成功不能解释为真实成功率严格等于零。原定配对t区间在全零观测下退化，因此不报告虚假的[0,0]区间，也不报告有意义的t检验p值。改用每开局“任一最终学生成功”与初始学生成功的单侧精确二项上界，再做Bonferroni组合，得到保守的差值界。该方法是在看到零事件后为处理统计边界而补充的。',f"最终平均差的样本估计为0个百分点；保守95%区间约[{c['CI95PP'][0]:+.2f}, {c['CI95PP'][1]:+.2f}]个百分点，条件于这三个训练结果。",'', '## 补充排错对照（事后诊断）','','由于直接学生表现极低，另用同512个开局检查原查表模型：','', '| 原查表评分的用法 | 合出1536 |','|---|---:|']
for k,label in [('table','只挑单步估值最高的方向'),('two','沿用既有两步搜索策略')]:
 x=r['posthocDiagnostics'][k];lines.append(f"| {label} | {x['wins']}/{x['games']}（{100*x['wins']/x['games']:.2f}%） |")
lines+=['', '该对照表明，同一评分表是否配合搜索，实际表现差别很大。V11学生原本是搜索先验推荐器，不能假设拿掉搜索后仍然有接近原AI的实力。这个事后对照用于排错，不作为新的预先指定主要结论。','','## 验证与限制','','- 20个策略梯度有限差分检查通过，覆盖终局优势和采样温度；80个直接学生动作与原V11搜索根先验最大项一致。','- 原查表和初始学生哈希未变；所有新权重有限，未使用的价值头保持零。无训练/评估对局被截断。','- 本轮只测一个温度、学习率、终局奖励方案和有限训练量，没有证明其他探索、课程学习或更好的学生初始化无效。','- 无6144或浏览器端测试，网页不替换模型。','','训练程序、协议、全部模型、四轮训练曲线与逐局评估见 `training/v13-selfplay/`。']
Path('RL-V13-SELFPLAY.md').write_text('\n'.join(lines)+'\n')
